/*
 * A191284  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then floor(3x/2) and 2x are in a.
 * https://oeis.org/A191284
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 53, u16 n <= 4209, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A191284:
   Generate by starting with a(1)=1 and, for each x already
   in the sequence, inserting floor(3x/2) and 2x.  
   This implementation uses a min‑heap to produce the next smallest
   element and stores the growing sequence in a dynamically
   allocated array.  The code works for arbitrary-precision seq_t
   by casting the results of memory allocation in the C++ path. */

#include <stdlib.h>
#include <stdbool.h>

/* Global state --------------------------------------------------- */

static seq_t *sequence = NULL;   /* Sorted list of generated terms   */
static idx_t  seq_len   = 0;     /* Current number of terms          */
static size_t seq_cap   = 0;     /* Allocated capacity of the array   */

static seq_t *heap      = NULL;  /* Min‑heap of pending candidates   */
static size_t heap_len  = 0;     /* Number of elements in the heap   */
static size_t heap_cap  = 0;     /* Allocated capacity of the heap   */

/* Helper functions ------------------------------------------------ */

/* Binary search: true if val occurs in arr[0 .. len-1] (arr sorted).  */
static bool seq_contains(const seq_t *arr, idx_t len, seq_t val) {
    size_t low = 0, high = (size_t)len;
    while (low < high) {
        size_t mid = (low + high) / 2;
        if (arr[mid] < val)
            low = mid + 1;
        else
            high = mid;
    }
    return (low < (size_t)len && arr[low] == val);
}

/* Grow the global sequence array if needed. */
static void grow_sequence(void) {
    if (seq_len == seq_cap) {
        seq_cap = (seq_cap == 0) ? 64 : seq_cap * 2;
        sequence = (seq_t*)realloc(sequence, seq_cap * sizeof(seq_t));
    }
}

/* Push a value onto the min‑heap.  */
static void heap_push(seq_t val) {
    if (heap_len == heap_cap) {
        heap_cap = (heap_cap == 0) ? 64 : heap_cap * 2;
        heap = (seq_t*)realloc(heap, heap_cap * sizeof(seq_t));
    }
    size_t i = heap_len++;
    while (i > 0) {
        size_t parent = (i - 1) / 2;
        if (heap[parent] <= val)
            break;
        heap[i] = heap[parent];
        i = parent;
    }
    heap[i] = val;
}

/* Pop the smallest element from the heap.  */
static seq_t heap_pop(void) {
    seq_t top = heap[0];
    heap_len--;
    seq_t last = heap[heap_len];
    size_t i = 0;
    while (true) {
        size_t left = 2 * i + 1;
        if (left >= heap_len) break;
        size_t right = left + 1;
        size_t smallest = (right < heap_len && heap[right] < heap[left]) ? right : left;
        if (heap[smallest] >= last) break;
        heap[i] = heap[smallest];
        i = smallest;
    }
    heap[i] = last;
    return top;
}

/* Ensure that the global sequence contains at least n terms.  */
static void ensure_sequence(idx_t n) {
    if (sequence == NULL) {
        seq_cap = 64;
        sequence = (seq_t*)calloc(seq_cap, sizeof(seq_t));
        seq_len = 0;
    }
    if (heap == NULL) {
        heap_cap = 64;
        heap = (seq_t*)calloc(heap_cap, sizeof(seq_t));
        heap_len = 0;
    }

    /* Seed with the first term if the sequence is empty.  */
    if (seq_len == 0) {
        sequence[0] = (seq_t)1;
        seq_len = 1;
        seq_t child1 = (sequence[0] * (seq_t)3) / (seq_t)2;
        seq_t child2 = sequence[0] * (seq_t)2;
        if (!seq_contains(sequence, seq_len, child1))
            heap_push(child1);
        if (!seq_contains(sequence, seq_len, child2))
            heap_push(child2);
    }

    /* Generate terms until we have at least n.  */
    while (seq_len < n) {
        seq_t cand;
        /* Skip duplicates that might already be in the sequence. */
        do {
            cand = heap_pop();
        } while (seq_contains(sequence, seq_len, cand));

        grow_sequence();
        sequence[seq_len++] = cand;

        /* Add the two children of the new value to the heap.  */
        seq_t c1 = (cand * (seq_t)3) / (seq_t)2;
        seq_t c2 = cand * (seq_t)2;
        if (!seq_contains(sequence, seq_len, c1))
            heap_push(c1);
        if (!seq_contains(sequence, seq_len, c2))
            heap_push(c2);
    }
}

/* Public function required by the build system. */
seq_t a(idx_t n) {
    if (n == 0)
        return (seq_t)0;            /* undefined, but harmless */
    ensure_sequence(n);
    return sequence[n - 1];
}
